  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "CI",
      "years": [2018, 2024],
      "pattern": "shock",
      "direction": "decrease then increase",
      "magnitude": "dip to ~0.73 A/E in 2019, sustained elevation to ~1.08 A/E from 2020-2024",
      "confidence": 0.9,
      "evidence": [
        "ae_ci_by_year.csv shows A/E dropping from 0.93 (2017) to 0.73 (2019), then jumping to 1.07 (2020) and holding 1.05-1.10 through 2024",
        "z-scores -6.0 (2018) and -8.9 (2019) confirm statistical significance of the dip; post-2019 years show z-scores +2.4 to +3.7",
        "evidence pack notes 2y dip excursion score 6.7 and step +0.156 at 2020, with level at series end +0.058 vs baseline"
      ],
      "recommended_action": "Investigate CI underwriting guidelines, benefit definitions, or claims reporting/processing changes implemented around 2018-2020; assess if the post-2019 elevation reflects a genuine experience deterioration requiring pricing and valuation assumption updates."
    }
  ]
}

